#include "../easyWave-cuda/kernels.cuh"
#define CHECK(x) do{auto e=(x);if(e!=cudaSuccess){fprintf(stderr,"CUDA:%s\n",cudaGetErrorString(e));exit(2);}}while(0)
constexpr int NX=23,NY=19,NN=NX*NY*12,STEPS=8;
template<typename T>struct Buf{T*base;T*p;int n;Buf(int n):n(n){CHECK(cudaMalloc(&base,(n+32)*sizeof(T)));p=base+16;std::vector<T>v(n+32,T(-8192));CHECK(cudaMemcpy(base,v.data(),v.size()*sizeof(T),cudaMemcpyHostToDevice));}~Buf(){cudaFree(base);}std::vector<T>get(){std::vector<T>x(n);CHECK(cudaMemcpy(x.data(),p,n*sizeof(T),cudaMemcpyDeviceToHost));return x;}void put(const T*x){CHECK(cudaMemcpy(p,x,n*sizeof(T),cudaMemcpyHostToDevice));}void guards(std::vector<double>&v){std::vector<T>x(n+32);CHECK(cudaMemcpy(x.data(),base,x.size()*sizeof(T),cudaMemcpyDeviceToHost));for(int j=0;j<16;j++)v.push_back(x[j]);for(int j=n+16;j<n+32;j++)v.push_back(x[j]);}};
struct Case{int id;Buf<float>node{NN},r6{NY+1},c1{NX+1},c2{NY+1},c3{NX+1},c4{NY+1};Buf<int>b0{1},b1{1},b2{1},b3{1};std::vector<float>input;std::vector<double>oracle;int initial[4];Case(int id):id(id){std::string root="/home/imo/HeCBench_julia/src/easyWave-julia/";std::ifstream f(root+"study_case"+std::to_string(id)+"_f32.bin",std::ios::binary);input.resize(5352);f.read((char*)input.data(),input.size()*4);if(!f)exit(3);std::ifstream o(root+"oracle_case"+std::to_string(id)+"_f64.bin",std::ios::binary);oracle.resize(173084);o.read((char*)oracle.data(),oracle.size()*8);if(!o)exit(3);int q=0;for(auto a:{&node,&r6,&c1,&c2,&c3,&c4}){a->put(input.data()+q);q+=a->n;}int init[]={id==1?5:2,id==1?5:2,id==1?19:22,id==1?15:18};std::copy(init,init+4,initial);}void reset(){node.put(input.data());}void guards(std::vector<double>&g){for(auto a:{&node,&r6,&c1,&c2,&c3,&c4})a->guards(g);for(auto a:{&b0,&b1,&b2,&b3})a->guards(g);}std::vector<int>pipeline(bool capture,std::vector<double>&states,std::vector<double>&bt){int b[4];std::copy(initial,initial+4,b);Buf<int>*bs[]={&b0,&b1,&b2,&b3};for(int step=0;step<STEPS;step++){dim3 blocks((b[3]-b[1]+16)/16,(b[2]-b[0]+16)/16);for(int stage=1;stage<=4;stage++){if(stage==1)kernel<<<blocks,dim3(16,16)>>>(node.p,r6.p,b[0],b[1],b[2],b[3],NY,1e-6f,1e-4f,step);if(stage==2)kernel2<<<1,1>>>(node.p,c1.p,c2.p,c3.p,c4.p,b[0],b[1],b[2],b[3],NY,NX);if(stage==3)kernel3<<<blocks,dim3(16,16)>>>(node.p,r6.p,b[0],b[1],b[2],b[3],NY);if(stage==4){for(int k=0;k<4;k++)bs[k]->put(b+k);kernel4<<<1,1>>>(node.p,c1.p,c2.p,c3.p,c4.p,b0.p,b1.p,b2.p,b3.p,NY,NX,1e-4f);for(int k=0;k<4;k++){auto x=bs[k]->get();b[k]=x[0];}if(capture)bt.insert(bt.end(),b,b+4);}CHECK(cudaGetLastError());if(capture){auto a=node.get();states.insert(states.end(),a.begin(),a.end());}}}CHECK(cudaDeviceSynchronize());return std::vector<int>(b,b+4);}};
int main(){Case a(1),b(2);std::vector<double>dummy;for(auto c:{&a,&b}){c->reset();c->pipeline(false,dummy,dummy);}bool all=true;for(int trial=1;trial<=5;trial++){std::vector<double>prefix,outputs,guards;double times[2],ma=0,mr=0,scaled=0;bool ok=true;for(auto c:{&a,&b}){c->reset();CHECK(cudaDeviceSynchronize());for(auto buf:{&c->node,&c->r6,&c->c1,&c->c2,&c->c3,&c->c4}){auto v=buf->get();prefix.insert(prefix.end(),v.begin(),v.end());}double params[]={NX,NY,STEPS,double(c->initial[0]),double(c->initial[1]),double(c->initial[2]),double(c->initial[3]),double(1e-6f),double(1e-4f),double(1e-4f),1,16,16};prefix.insert(prefix.end(),params,params+13);auto start=std::chrono::steady_clock::now();auto tb=c->pipeline(false,dummy,dummy);times[c->id-1]=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();auto final=c->node.get();std::vector<double>actual(final.begin(),final.end());c->guards(guards);c->reset();std::vector<double>states,bt;auto cb=c->pipeline(true,states,bt);actual.insert(actual.end(),states.begin(),states.end());actual.insert(actual.end(),bt.begin(),bt.end());c->guards(guards);ok&=tb==cb&&actual.size()==c->oracle.size();for(size_t i=0;i<actual.size();i++){double e=std::abs(actual[i]-c->oracle[i]);ma=std::max(ma,e);mr=std::max(mr,e/std::max(std::abs(c->oracle[i]),2.220446049250313e-16));scaled=std::max(scaled,e/(1e-7+1e-5*std::abs(c->oracle[i])));ok&=std::isfinite(actual[i])&&e<=1e-7+1e-5*std::abs(c->oracle[i]);if(i>=actual.size()-32)ok&=actual[i]==c->oracle[i];}if(c->id==2)ok&=std::equal(final.begin(),final.end(),c->input.begin());outputs.insert(outputs.end(),actual.begin(),actual.end());}for(auto g:guards)ok&=g==-8192;all&=ok;auto artifact=prefix;artifact.insert(artifact.end(),outputs.begin(),outputs.end());artifact.insert(artifact.end(),guards.begin(),guards.end());std::string path=std::string(getenv("STUDY_OUTPUT_DIR"))+"/trial"+std::to_string(trial)+".bin";std::ofstream f(path,std::ios::binary);f.write((char*)artifact.data(),artifact.size()*8);f.close();printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":347448,\"max_abs_error\":%.12g,\"max_rel_error\":%.12g,\"relative_error_floor\":2.220446049250313e-16,\"max_scaled_oracle_error\":%.12g,\"timing_region\":\"sum_two_8step_shallow_water_four_kernel_pipelines_with_adaptive_bounds_H2D_D2H\",\"jit_excluded\":true,\"internal_repeats\":1,\"timed_steps\":8,\"timed_cases\":2,\"untimed_full_stage_capture_reexecution\":true,\"component_time_seconds\":[%.12g,%.12g],\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,times[0]+times[1],ok?"true":"false",ma,mr,scaled,times[0],times[1],path.c_str(),artifact.size());}return all?0:1;}
